insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('DE', 'default', 'Referenzkontenplan nach der Gliederung der §§ 266 und 275 HGB', '{"en":"Reference chart of accounts following sections 266 and 275 HGB"}'::jsonb, true, 'companies', array['DE-HGB-266-BS', 'DE-HGB-275-GKV']::text[], null, 'HGB § 238 Abs. 1 verpflichtet jeden Kaufmann, Bücher zu führen, schreibt aber keinen Kontenplan vor. Die verbreiteten Standardkontenrahmen SKR 03 und SKR 04 sind Werke der DATEV eG, die ohne offene Lizenz veröffentlicht werden; dieser Plan übernimmt weder ihre Nummern noch ihre Bezeichnungen. Er ist eigenständig: vierstellige Nummern, deren erste Ziffer den Abschnitt der Bilanz nach § 266 (1 Anlagevermögen, 2 Umlaufvermögen, 3 Aktiva C bis E, 4 Eigenkapital, 5 Rückstellungen, 6 Verbindlichkeiten, 7 Passiva D und E) oder der Gewinn- und Verlustrechnung nach § 275 Abs. 2 (8 Posten 1 bis 8, 9 Posten 9 bis 16) bezeichnet und deren zweite und dritte Ziffer die römische und arabische Nummer des Postens wiedergeben; die Bezeichnungen der Konten folgen dem Wortlaut der gesetzlichen Posten.', 'hgb')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

