values
  ('DE', 'DE-P-05', 'Vorsteuer 5 %', '{"en":"Input VAT 5 %"}'::jsonb, 'Befristeter ermäßigter Steuersatz 2020; Zeile 38 (Kz. 66)', 'percent', 5, 'purchase', 'domestic', date '2020-07-01', date '2020-12-31', 'UStG § 15 Abs. 1 Satz 1 Nr. 1; Satz nach § 28 Abs. 2 vom 1. Juli bis 31. Dezember 2020.', 'S', null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-07', 'Vorsteuer 7 %', '{"en":"Input VAT 7 %"}'::jsonb, 'Vorsteuer aus Rechnungen anderer Unternehmer; Zeile 38 (Kz. 66)', 'percent', 7, 'purchase', 'domestic', date '1983-07-01', null, 'UStG § 15 Abs. 1 Satz 1 Nr. 1; Satz nach § 12 Abs. 2.', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-13B-19', 'Inländische Leistung nach § 13b Abs. 2 Nr. 4 bis 11 UStG 19 %', '{"en":"Domestic supply under section 13b(2) nos. 4 to 11 UStG 19 %"}'::jsonb, 'Zum Beispiel Bauleistungen an einen bauleistenden Unternehmer; Zeile 32 (Kz. 84/85) und Zeile 41 (Kz. 67)', 'percent', 19, 'purchase', 'domestic_reverse_charge', date '2002-01-01', null, 'UStG § 13b Abs. 2 Nr. 4 bis 11 in Verbindung mit Abs. 5 — für Bauleistungen an einen Unternehmer, der selbst nachhaltig Bauleistungen erbringt, für Gebäudereinigung, Lieferungen von Gold, Mobilfunkgeräten, Metallen und die übrigen dort genannten Umsätze schuldet der Leistungsempfänger die Steuer; Vorsteuerabzug nach § 15 Abs. 1 Satz 1 Nr. 4.', 'AE', 'VATEX-EU-AE', 220, 'vat', true, array['buyer_status', 'supply_nature']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-16', 'Vorsteuer 16 %', '{"en":"Input VAT 16 %"}'::jsonb, 'Befristeter allgemeiner Steuersatz 2020; Zeile 38 (Kz. 66)', 'percent', 16, 'purchase', 'domestic', date '2020-07-01', date '2020-12-31', 'UStG § 15 Abs. 1 Satz 1 Nr. 1; Satz nach § 28 Abs. 1 vom 1. Juli bis 31. Dezember 2020.', 'S', null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-19', 'Vorsteuer 19 %', '{"en":"Input VAT 19 %"}'::jsonb, 'Vorsteuer aus Rechnungen anderer Unternehmer; Zeile 38 (Kz. 66)', 'percent', 19, 'purchase', 'domestic', date '2007-01-01', null, 'UStG § 15 Abs. 1 Satz 1 Nr. 1 — abziehbar ist die gesetzlich geschuldete Steuer für Lieferungen und sonstige Leistungen, die von einem anderen Unternehmer für das Unternehmen ausgeführt worden sind, sofern eine Rechnung nach §§ 14, 14a vorliegt. Satz nach § 12 Abs. 1.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-19-NA', 'Nicht abziehbare Vorsteuer 19 %', '{"en":"Non-deductible input VAT 19 %"}'::jsonb, 'Aufwendungen nach § 4 Abs. 5 EStG, zum Beispiel Geschenke über 50 Euro: die Steuer folgt dem Aufwandskonto', 'percent', 19, 'purchase', 'domestic', date '2007-01-01', null, 'UStG § 15 Abs. 1a — nicht abziehbar sind Vorsteuerbeträge, die auf Aufwendungen entfallen, für die das Abzugsverbot des § 4 Abs. 5 Satz 1 Nr. 1 bis 4, 7 oder des § 12 Nr. 1 des Einkommensteuergesetzes gilt; ausgenommen sind Bewirtungsaufwendungen, soweit § 4 Abs. 5 Satz 1 Nr. 2 EStG einen Abzug angemessener und nachgewiesener Aufwendungen ausschließt. Die Steuer wird daher Teil der Anschaffungskosten und erscheint in keiner Zeile der Voranmeldung.', 'S', null, 170, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-DRITT-19', 'Leistung eines im Drittland ansässigen Unternehmers 19 %', '{"en":"Service from a supplier established outside the Union 19 %"}'::jsonb, 'Leistungsempfänger als Steuerschuldner; Zeile 32 (Kz. 84/85) und Zeile 41 (Kz. 67)', 'percent', 19, 'purchase', 'foreign_services_received', date '2002-01-01', null, 'UStG § 13b Abs. 2 Nr. 1 in Verbindung mit Abs. 5 Satz 1 — für Werklieferungen und nicht unter Abs. 1 fallende sonstige Leistungen eines im Ausland ansässigen Unternehmers schuldet der Leistungsempfänger die Steuer; Steuerentstehung nach § 13b Abs. 2 mit Ausstellung der Rechnung, spätestens mit Ablauf des der Ausführung folgenden Kalendermonats; Vorsteuerabzug nach § 15 Abs. 1 Satz 1 Nr. 4. Die Rechnung des ausländischen Lieferers fällt nicht unter EN 16931, daher keine Kategorie.', null, null, 210, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-EUDL-19', 'Sonstige Leistung eines im übrigen Gemeinschaftsgebiet ansässigen Unternehmers 19 %', '{"en":"Service from a supplier established in another Member State 19 %"}'::jsonb, 'Leistungsempfänger als Steuerschuldner; Zeile 30 (Kz. 46/47) und Zeile 41 (Kz. 67)', 'percent', 19, 'purchase', 'intracom_acquisition_services', date '2010-01-01', null, 'UStG § 13b Abs. 1 in Verbindung mit Abs. 5 Satz 1 — für nach § 3a Abs. 2 im Inland steuerpflichtige sonstige Leistungen eines im übrigen Gemeinschaftsgebiet ansässigen Unternehmers schuldet der Leistungsempfänger die Steuer; sie entsteht mit Ablauf des Voranmeldungszeitraums, in dem die Leistung ausgeführt worden ist, und ist nach § 15 Abs. 1 Satz 1 Nr. 4 als Vorsteuer abziehbar.', 'K', 'VATEX-EU-IC', 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-IGE-07', 'Innergemeinschaftlicher Erwerb 7 %', '{"en":"Intra-Community acquisition of goods 7 %"}'::jsonb, 'Steuer und Vorsteuer aus dem Erwerb; Zeile 26 (Kz. 93) und Zeile 39 (Kz. 61)', 'percent', 7, 'purchase', 'intracom_acquisition_goods', date '1993-01-01', null, 'UStG § 1a in Verbindung mit § 12 Abs. 2 Nr. 1 — Erwerb der in Anlage 2 bezeichneten Gegenstände; Steuerentstehung § 13 Abs. 1 Nr. 6, Vorsteuerabzug § 15 Abs. 1 Satz 1 Nr. 3.', 'K', 'VATEX-EU-IC', 190, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-P-IGE-19', 'Innergemeinschaftlicher Erwerb 19 %', '{"en":"Intra-Community acquisition of goods 19 %"}'::jsonb, 'Steuer und Vorsteuer aus dem Erwerb; Zeile 25 (Kz. 89) und Zeile 39 (Kz. 61)', 'percent', 19, 'purchase', 'intracom_acquisition_goods', date '2007-01-01', null, 'UStG § 1 Abs. 1 Nr. 5 und § 1a — der innergemeinschaftliche Erwerb im Inland gegen Entgelt ist steuerbar; die Steuer entsteht nach § 13 Abs. 1 Nr. 6 mit Ausstellung der Rechnung, spätestens mit Ablauf des dem Erwerb folgenden Kalendermonats; Steuerschuldner ist nach § 13a Abs. 1 Nr. 2 der Erwerber, der sie nach § 15 Abs. 1 Satz 1 Nr. 3 als Vorsteuer abzieht.', 'K', 'VATEX-EU-IC', 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-00-PV', 'Umsatzsteuer 0 % Photovoltaik', '{"en":"Output VAT 0 % photovoltaic"}'::jsonb, 'Nullsatz für Solarmodule, wesentliche Komponenten und Speicher; Zeile 15 (Kz. 87)', 'percent', 0, 'sale', 'domestic', date '2023-01-01', null, 'UStG § 12 Abs. 3 — die Steuer ermäßigt sich auf 0 Prozent für die Lieferung und Installation von Solarmodulen an den Betreiber einer Photovoltaikanlage einschließlich der wesentlichen Komponenten und der Speicher, wenn die Anlage auf oder in der Nähe von Privatwohnungen, Wohnungen oder dem Gemeinwohl dienenden Gebäuden installiert wird; die Voraussetzung gilt als erfüllt bei einer Bruttoleistung laut Marktstammdatenregister von nicht mehr als 30 kW (peak). In Kraft seit dem 1. Januar 2023 (Jahressteuergesetz 2022). Es ist ein ermäßigter Steuersatz und keine Steuerbefreiung, daher die Kategorie Z.', 'Z', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-05', 'Umsatzsteuer 5 %', '{"en":"Output VAT 5 %"}'::jsonb, 'Befristeter ermäßigter Steuersatz 1. Juli bis 31. Dezember 2020; Zeile 16 (Kz. 35/36)', 'percent', 5, 'sale', 'domestic', date '2020-07-01', date '2020-12-31', 'UStG § 28 Abs. 2 — § 12 Abs. 2 ist vom 1. Juli 2020 bis 31. Dezember 2020 mit der Maßgabe anzuwenden, dass sich die Steuer für die in den Nummern 1 bis 15 genannten Umsätze auf 5 Prozent ermäßigt. Zeile 16 der Voranmeldung 2026 wie beim Satz von 16 Prozent.', 'S', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-07', 'Umsatzsteuer 7 %', '{"en":"Output VAT 7 %"}'::jsonb, 'Ermäßigter Steuersatz nach Anlage 2 und § 12 Abs. 2, nach Nr. 15 auch Restaurant- und Verpflegungsdienstleistungen ohne Getränke; Zeile 14', 'percent', 7, 'sale', 'domestic', date '1983-07-01', null, 'UStG § 12 Abs. 2 — die Steuer ermäßigt sich auf sieben Prozent für die dort genannten Umsätze, insbesondere Nr. 1 die Lieferung der in Anlage 2 bezeichneten Gegenstände und Nr. 15 die Restaurant- und Verpflegungsdienstleistungen mit Ausnahme der Abgabe von Getränken. Vom 1. Juli bis 31. Dezember 2020 galten nach § 28 Abs. 2 5 Prozent.', 'S', null, 20, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-13B', 'Steuerpflichtiger Umsatz, Steuerschuldner Leistungsempfänger', '{"en":"Domestic supply, customer liable for the tax"}'::jsonb, 'Leistender Unternehmer bei § 13b Abs. 2 (z. B. Bauleistungen, Gebäudereinigung); Zeile 34 (Kz. 60)', 'percent', 0, 'sale', 'domestic_reverse_charge', date '2002-01-01', null, 'UStG § 13b Abs. 2 und 5 — für die dort genannten Umsätze schuldet der Leistungsempfänger die Steuer; § 14a Abs. 5 verlangt die Angabe „Steuerschuldnerschaft des Leistungsempfängers“ und schließt den gesonderten Steuerausweis aus. Der leistende Unternehmer erklärt die Bemessungsgrundlage in Zeile 34 (Kz. 60).', 'AE', 'VATEX-EU-AE', 90, 'vat', true, array['buyer_status', 'supply_nature']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-16', 'Umsatzsteuer 16 %', '{"en":"Output VAT 16 %"}'::jsonb, 'Befristeter allgemeiner Steuersatz 1. Juli bis 31. Dezember 2020; Zeile 16 (Kz. 35/36)', 'percent', 16, 'sale', 'domestic', date '2020-07-01', date '2020-12-31', 'UStG § 28 Abs. 1 — § 12 Abs. 1 ist vom 1. Juli 2020 bis 31. Dezember 2020 mit der Maßgabe anzuwenden, dass die Steuer 16 Prozent beträgt. Die Anleitung zur Voranmeldung 2026 (USt 1 E, Zeilen 13 bis 16) ordnet Änderungen von Bemessungsgrundlagen dieser Umsätze der Zeile 16 zu, den Umsätzen zu anderen Steuersätzen, mit selbst berechnetem Steuerbetrag.', 'S', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-19', 'Umsatzsteuer 19 %', '{"en":"Output VAT 19 %"}'::jsonb, 'Allgemeiner Steuersatz; Zeile 13 der Voranmeldung', 'percent', 19, 'sale', 'domestic', date '2007-01-01', null, 'UStG § 12 Abs. 1 — die Steuer beträgt für jeden steuerpflichtigen Umsatz 19 Prozent der Bemessungsgrundlage, seit dem 1. Januar 2007 (Haushaltsbegleitgesetz 2006). Vom 1. Juli bis 31. Dezember 2020 galten nach § 28 Abs. 1 16 Prozent; maßgeblich ist nach § 27 Abs. 1 der Zeitpunkt der Leistung, nicht das Rechnungsdatum, so dass dieser Code auch in jenem Halbjahr für eine vorher ausgeführte Leistung gültig bleibt.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-AUSF', 'Steuerfreie Ausfuhrlieferung', '{"en":"Exempt export of goods"}'::jsonb, 'Lieferung in das Drittlandsgebiet; Zeile 22 (Kz. 43)', 'percent', 0, 'sale', 'export', date '1980-01-01', null, 'UStG § 4 Nr. 1 Buchst. a in Verbindung mit § 6 — steuerfrei sind die Ausfuhrlieferungen; die Voraussetzungen sind nach § 6 Abs. 4 buch- und belegmäßig nachzuweisen (UStDV §§ 8 ff.). Die Anleitung zur Voranmeldung 2026 ordnet sie der Zeile 22 zu, den weiteren steuerfreien Umsätzen mit Vorsteuerabzug.', 'G', 'VATEX-EU-G', 80, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-EUDL', 'Sonstige Leistung im übrigen Gemeinschaftsgebiet', '{"en":"Service taxable in another Member State"}'::jsonb, 'Nicht steuerbar im Inland, Steuerschuldner ist der Leistungsempfänger; Zeile 35 (Kz. 21) und Zusammenfassende Meldung', 'percent', 0, 'sale', 'intracom_services', date '2010-01-01', null, 'UStG § 3a Abs. 2 — eine sonstige Leistung an einen Unternehmer für dessen Unternehmen wird an dem Ort ausgeführt, von dem aus der Empfänger sein Unternehmen betreibt; § 18b Satz 1 Nr. 2 verlangt ihre Angabe in der Voranmeldung, § 18a Abs. 2 in der Zusammenfassenden Meldung, § 14a Abs. 1 die Rechnung mit der Angabe „Steuerschuldnerschaft des Leistungsempfängers“ und beiden Identifikationsnummern.', 'K', 'VATEX-EU-IC', 70, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-FREI-12', 'Steuerfreie Vermietung und Verpachtung von Grundstücken', '{"en":"Exempt letting of immovable property"}'::jsonb, 'Ohne Vorsteuerabzug; Zeile 23 (Kz. 48)', 'percent', 0, 'sale', 'exempt', date '1980-01-01', null, 'UStG § 4 Nr. 12 Buchst. a — steuerfrei ist die Vermietung und die Verpachtung von Grundstücken; der Vorsteuerabzug ist nach § 15 Abs. 2 Satz 1 Nr. 1 ausgeschlossen, sofern nicht nach § 9 verzichtet wird. Richtlinie 2006/112/EG Art. 135 Abs. 1 Buchst. l, daher VATEX-EU-135-1.', 'E', 'VATEX-EU-135-1', 100, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-FREI-14', 'Steuerfreie Heilbehandlung', '{"en":"Exempt medical care"}'::jsonb, 'Heilbehandlungen im Bereich der Humanmedizin; ohne Vorsteuerabzug; Zeile 23 (Kz. 48)', 'percent', 0, 'sale', 'exempt', date '1980-01-01', null, 'UStG § 4 Nr. 14 Buchst. a — steuerfrei sind Heilbehandlungen im Bereich der Humanmedizin, die im Rahmen der Ausübung der Tätigkeit als Arzt, Zahnarzt, Heilpraktiker, Physiotherapeut, Hebamme oder einer ähnlichen heilberuflichen Tätigkeit durchgeführt werden. Richtlinie 2006/112/EG Art. 132 Abs. 1 Buchst. c, daher VATEX-EU-132-1C.', 'E', 'VATEX-EU-132-1C', 110, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-IGL', 'Steuerfreie innergemeinschaftliche Lieferung', '{"en":"Exempt intra-Community supply of goods"}'::jsonb, 'An Abnehmer mit Umsatzsteuer-Identifikationsnummer; Zeile 19 (Kz. 41) und Zusammenfassende Meldung', 'percent', 0, 'sale', 'intracom_goods', date '1993-01-01', null, 'UStG § 4 Nr. 1 Buchst. b in Verbindung mit § 6a Abs. 1 — steuerfrei ist die innergemeinschaftliche Lieferung an einen Abnehmer, der eine ihm von einem anderen Mitgliedstaat erteilte gültige Umsatzsteuer-Identifikationsnummer verwendet, wenn die Lieferung in der Zusammenfassenden Meldung nach § 18a zutreffend angegeben ist (§ 4 Nr. 1 Buchst. b letzter Halbsatz); § 14a Abs. 3 verlangt die Rechnung bis zum 15. Tag des Folgemonats mit beiden Identifikationsnummern.', 'K', 'VATEX-EU-IC', 60, 'vat', true, array['buyer_status', 'transport_evidence']::tax_condition[], null, false, false, null, 'ustg', null, null, null, null),
  ('DE', 'DE-S-NSTB', 'Nicht steuerbarer Umsatz, Leistungsort im Drittland', '{"en":"Not taxable in Germany, place of supply outside the Union"}'::jsonb, 'Zum Beispiel sonstige Leistung an einen Unternehmer im Drittland; Zeile 36 (Kz. 45)', 'percent', 0, 'sale', 'not_subject', date '2010-01-01', null, 'UStG § 1 Abs. 1 Nr. 1 in Verbindung mit § 3a Abs. 2 — eine sonstige Leistung an einen Unternehmer mit Sitz im Drittlandsgebiet ist im Inland nicht steuerbar. Die Anleitung zur Voranmeldung 2026 (Zeile 36) verlangt die übrigen nicht steuerbaren Umsätze, deren Leistungsort nicht im Inland liegt, in Kz. 45.', 'O', 'VATEX-EU-O', 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ustg', null, null, null, null)
