insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('DE', 'DE-USTVA-2026', 'Umsatzsteuer-Voranmeldung 2026 (Vordruck USt 1 A)', array['month', 'quarter']::declaration_period[], null, date '2026-01-01', null, 'UStG § 18 Abs. 1 und 2 — Voranmeldung nach amtlich vorgeschriebenem Datensatz über die amtlich bestimmte Schnittstelle bis zum zehnten Tag nach Ablauf jedes Voranmeldungszeitraums. Voranmeldungszeitraum ist das Kalendervierteljahr; der Kalendermonat, wenn die Steuer des Vorjahres mehr als 9 000 Euro betrug, und im Jahr der Aufnahme der Tätigkeit und im folgenden Jahr; bei nicht mehr als 2 000 Euro kann das Finanzamt von der Abgabe befreien; nach Abs. 2a kann der Unternehmer bei einem Überschuss von mehr als 9 000 Euro im Vorjahr den Monat wählen. Weil der Zeitraum von einer Größe des Unternehmens abhängt, schlägt das Pack keinen vor. Die Boxen sind die Kennzahlen des Vordruckmusters USt 1 A 2026 (BMF-Schreiben vom 29. Dezember 2025); die drei Summenzeilen ohne Kennzahl (Zeilen 37, 45 und 48) tragen die Codes Z37, Z45 und Z48. Ein Vordruck eines anderen Jahres ist ein neuer Code mit eigenem valid_from.', true,'day_of_month_after_period'::filing_deadline_rule, 10, null, 'UStG § 18 Abs. 1 Satz 1 und Satz 4 — die Voranmeldung ist bis zum zehnten Tag nach Ablauf des Voranmeldungszeitraums zu übermitteln und die Vorauszahlung an diesem Tag fällig. Die Dauerfristverlängerung nach §§ 46 bis 48 UStDV verschiebt beide Fristen um einen Monat, bei monatlicher Abgabe gegen eine Sondervorauszahlung von einem Elftel der Vorjahresvorauszahlungen (§ 47 Abs. 1); sie gilt nur für Unternehmer, denen sie auf Antrag gewährt wurde, und wird deshalb nicht als plus_days angegeben. Fällt das Fristende auf einen Sonnabend, Sonntag oder gesetzlichen Feiertag, endet die Frist nach § 108 Abs. 3 AO mit dem nächstfolgenden Werktag, was der Kern ohne Feiertagskalender nicht abbildet.', 'ustg', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

