  ('DE', 'DE-USTVA-2026', '62', 'tax', 'Entstandene Einfuhrumsatzsteuer', '{"en":"Import VAT incurred"}'::jsonb, 390, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 40, Kennzahl 62 — § 15 Abs. 1 Satz 1 Nr. 2 UStG. Keine Steuer des Packs schreibt in diese Zeile: die Einfuhrumsatzsteuer wird von der Zollverwaltung auf einem Einfuhrabgabenbescheid festgesetzt, nicht auf einer Rechnung, und der Kern kennt kein Dokument, dessen Betrag allein die Steuer ist (docs/international.md)', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '67', 'tax', 'Vorsteuerbeträge aus Leistungen im Sinne des § 13b UStG', '{"en":"Input VAT on supplies under section 13b UStG"}'::jsonb, 400, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 41, Kennzahl 67 — § 15 Abs. 1 Satz 1 Nr. 4 UStG', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '63', 'tax', 'Vorsteuerbeträge, die nach allgemeinen Durchschnittssätzen berechnet sind (§ 23a UStG)', '{"en":"Input VAT calculated at general flat rates (section 23a UStG)"}'::jsonb, 410, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 42, Kennzahl 63', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '59', 'tax', 'Vorsteuerabzug für innergemeinschaftliche Lieferungen neuer Fahrzeuge außerhalb eines Unternehmens sowie von Kleinunternehmern (§ 15 Abs. 4a UStG)', '{"en":"Input VAT on intra-Community supplies of new vehicles outside a business and by small businesses (section 15(4a) UStG)"}'::jsonb, 420, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 43, Kennzahl 59', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '64', 'tax', 'Berichtigung des Vorsteuerabzugs (§ 15a UStG)', '{"en":"Adjustment of input VAT deduction (section 15a UStG)"}'::jsonb, 430, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 44, Kennzahl 64 — zurückzuzahlende Vorsteuerbeträge mit Minuszeichen (Anleitung USt 1 E, Zeile 44)', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', 'Z45', 'total', 'Verbleibender Betrag (Zeile 37 abzüglich der Zeilen 38 bis 44)', '{"en":"Remaining amount (line 37 less lines 38 to 44)"}'::jsonb, 440, null, array['Z37']::text[], array['66', '61', '62', '67', '63', '59', '64']::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 45 — ohne Kennzahl, Code Z45 nach der Zeilennummer', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '65', 'tax', 'Steuer infolge des Wechsels der Besteuerungsform sowie Nachsteuer auf versteuerte Anzahlungen wegen Steuersatzänderung', '{"en":"Tax on a change of taxation method and additional tax on advance payments taxed before a rate change"}'::jsonb, 450, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 46, Kennzahl 65', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '69', 'tax', 'In Rechnungen unrichtig oder unberechtigt ausgewiesene Steuerbeträge (§ 14c UStG) und weitere geschuldete Steuerbeträge', '{"en":"Tax incorrectly or unjustifiably shown on invoices (section 14c UStG) and other tax owed"}'::jsonb, 460, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 47, Kennzahl 69 — auch Steuerbeträge nach § 6a Abs. 4 Satz 2, § 17 Abs. 1 Satz 7, § 25b Abs. 2 UStG und nach § 27 Abs. 40a UStG', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', 'Z48', 'total', 'Umsatzsteuer-Vorauszahlung/Überschuss (Summe der Zeilen 45 bis 47)', '{"en":"VAT advance payment or surplus (sum of lines 45 to 47)"}'::jsonb, 470, null, array['Z45', '65', '69']::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 48 — ohne Kennzahl, Code Z48 nach der Zeilennummer', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '39', 'tax', 'Abzug der festgesetzten Sondervorauszahlung für Dauerfristverlängerung', '{"en":"Deduction of the special advance payment for the permanent deadline extension"}'::jsonb, 480, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 49, Kennzahl 39 — in der Regel nur in der letzten Voranmeldung des Besteuerungszeitraums (§ 48 Abs. 4 UStDV); die Sondervorauszahlung beträgt nach § 47 Abs. 1 UStDV ein Elftel der Vorauszahlungen des Vorjahres. Keine Steuer des Packs schreibt in diese Zeile, sie wird von Hand erfasst', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '83', 'total', 'Verbleibende Umsatzsteuer-Vorauszahlung bzw. verbleibender Überschuss', '{"en":"Remaining VAT advance payment or remaining surplus"}'::jsonb, 490, null, array['Z48']::text[], array['39']::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 50, Kennzahl 83 — in jedem Fall auszufüllen; ein Überschuss wird mit Minuszeichen angegeben, deshalb ohne Untergrenze bei null. Fällig am 10. Tag nach Ablauf des Voranmeldungszeitraums (UStG § 18 Abs. 1 Satz 4)', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '50', 'base', 'Minderung der Bemessungsgrundlage nach § 17 Abs. 1 Sätze 1 und 2 in Verbindung mit Abs. 2 Nr. 1 Satz 1 UStG (in den Zeilen 13 bis 18 enthalten)', '{"en":"Reduction of the taxable amount for irrecoverable consideration (included in lines 13 to 18)"}'::jsonb, 500, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 51, Kennzahl 50 — Davon-Angabe bei Uneinbringlichkeit; kein Posting schreibt in diese Zeile, weil der Kern eine Gutschrift wegen Uneinbringlichkeit nicht von einer anderen unterscheidet', 'ustva-2026'),
  ('DE', 'DE-USTVA-2026', '37', 'tax', 'Minderung der abziehbaren Vorsteuerbeträge (in den Zeilen 38, 42 und 43 enthalten)', '{"en":"Reduction of deductible input VAT (included in lines 38, 42 and 43)"}'::jsonb, 510, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Vordruck USt 1 A 2026, Zeile 52, Kennzahl 37 — Davon-Angabe bei Uneinbringlichkeit, wie Kennzahl 50 ohne Posting', 'ustva-2026')
