insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('DE-HGB-266-BS', 'DE', 'default', 'Bilanz nach § 266 HGB', 'balance_sheet', 'DE-HGB', date '2016-01-01', null, 'Handelsgesetzbuch § 266 Abs. 1 bis 3 in der Fassung des Bilanzrichtlinie-Umsetzungsgesetzes (BilRUG) — Gliederung der Bilanz in Kontoform, Aktivseite Abs. 2 und Passivseite Abs. 3. Die Zeilen sind die gesetzlichen Posten mit Buchstaben, römischen und arabischen Zahlen, wie mittelgroße und große Kapitalgesellschaften sie ausweisen; kleine Kapitalgesellschaften (§ 267 Abs. 1) dürfen nach § 266 Abs. 1 Satz 3 nur die mit Buchstaben und römischen Zahlen bezeichneten Posten ausweisen, die hier als Summenzeilen vorhanden sind, Kleinstkapitalgesellschaften (§ 267a) nach Satz 4 nur die Buchstaben. Ein Jahresüberschuss des laufenden, noch nicht abgeschlossenen Geschäftsjahres erscheint erst nach dem Abschluss in Posten A.V.', 'hgb'),
  ('DE-HGB-275-GKV', 'DE', 'default', 'Gewinn- und Verlustrechnung nach § 275 Abs. 2 HGB (Gesamtkostenverfahren)', 'income_statement', 'DE-HGB', date '2016-01-01', null, 'Handelsgesetzbuch § 275 Abs. 1 und 2 in der Fassung des BilRUG — Staffelform nach dem Gesamtkostenverfahren, Posten 1 bis 17 in der gesetzlichen Reihenfolge. Das Umsatzkostenverfahren (Abs. 3) setzt eine Kostenstellenrechnung voraus, die der Kontenplan nicht abbildet, und wird von diesem Pack nicht geführt; die verkürzte Darstellung der Kleinstkapitalgesellschaften (Abs. 5) ebenfalls nicht. Kleine und mittelgroße Kapitalgesellschaften dürfen die Posten 1 bis 5 nach § 276 Satz 1 zum Rohergebnis zusammenfassen; die Einzelposten bleiben hier sichtbar.', 'hgb')
