update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'BGB § 288 Abs. 2 — Verzugszinsen bei Entgeltforderungen zwischen Unternehmern neun Prozentpunkte über dem Basiszinssatz nach § 247 BGB, den die Deutsche Bundesbank halbjährlich bekannt gibt; Abs. 5 — Pauschale von 40 Euro',
  numbering_legal_reference     = 'UStG § 14 Abs. 4 Satz 1 Nr. 4 — eine fortlaufende Nummer mit einer oder mehreren Zahlenreihen, die zur Identifizierung der Rechnung vom Rechnungsaussteller einmalig vergeben wird. Das Gesetz verlangt Einmaligkeit, keine lückenlose Folge, daher sequential und nicht gapless; mehrere Nummernkreise, etwa je Jahr, sind zulässig.',
  numbering_source_key          = 'ustg',
  payment_terms_legal_reference = 'BGB § 286 Abs. 3 Satz 1 — der Schuldner einer Entgeltforderung kommt spätestens in Verzug, wenn er nicht innerhalb von 30 Tagen nach Fälligkeit und Zugang einer Rechnung leistet; gegenüber einem Verbraucher nur, wenn die Rechnung auf diese Folge besonders hinweist. § 271a begrenzt vereinbarte Zahlungsfristen zwischen Unternehmern grundsätzlich auf 60 Tage.',
  payment_terms_source_key      = 'bgb',
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'UStG § 13 Abs. 1 Nr. 1 Buchst. a Satz 1 — bei der Besteuerung nach vereinbarten Entgelten entsteht die Steuer mit Ablauf des Voranmeldungszeitraums, in dem die Leistung ausgeführt worden ist (Grundsatz); Satz 4 — wird das Entgelt vor Ausführung der Leistung vereinnahmt, entsteht die Steuer insoweit mit Ablauf des Voranmeldungszeitraums der Vereinnahmung (Mindest-Istversteuerung). Beide Zweige zusammen sind earliest_of_delivery_or_payment. Nicht abgebildet: die Istversteuerung nach § 20 auf Antrag, die innergemeinschaftliche Lieferung und die Leistung nach § 3a Abs. 2 im übrigen Gemeinschaftsgebiet, die § 18b nach dem Rechnungsdatum, spätestens dem Ablauf des Folgemonats erklären lässt, und der innergemeinschaftliche Erwerb (§ 13 Abs. 1 Nr. 6) mit derselben Regel.',
  tax_point_source_key          = 'ustg',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'HGB § 239 Abs. 3 — eine Eintragung darf nicht in einer Weise verändert werden, dass der ursprüngliche Inhalt nicht mehr feststellbar ist; gleichlautend AO § 146 Abs. 4. Eine gebuchte Rechnung wird daher nur durch eine Stornorechnung oder Gutschrift berichtigt, die auf sie verweist.',
  posted_edit_policy_source_key = 'hgb',
  einvoice_profile              = 'xrechnung',
  einvoice_mandatory_from       = date '2025-01-01',
  einvoice_obligation           = 'mandatory',
  einvoice_legal_reference      = 'UStG § 14 Abs. 1 Satz 3 und 6 und Abs. 2 Satz 2 Nr. 1 in der Fassung des Wachstumschancengesetzes — für eine Leistung zwischen im Inland ansässigen Unternehmern ist die Rechnung als elektronische Rechnung in einem strukturierten Format nach EN 16931 auszustellen; seit dem 1. Januar 2025 muss jeder inländische Unternehmer eine E-Rechnung empfangen können, wofür ein E-Mail-Postfach genügt (BMF-Schreiben vom 15. Oktober 2025). Die Pflicht zur Ausstellung folgt dem Übergangskalender des § 27 Abs. 38: bis 31. Dezember 2026 darf jeder Unternehmer noch Papier- oder andere elektronische Rechnungen ausstellen; bis 31. Dezember 2027 nur, wer im Vorjahr einen Gesamtumsatz nach § 19 Abs. 2 von nicht mehr als 800 000 Euro hatte, oder mit Zustimmung des Empfängers per EDI. Die Ausstellung ist damit ab 1. Januar 2027 für Unternehmer über 800 000 Euro und ab 1. Januar 2028 für alle Pflicht; mandatory_from trägt das Datum des Empfangs. Kleinbetragsrechnungen bis 250 Euro (UStDV § 33) und Rechnungen von Kleinunternehmern (§ 34a) dürfen immer als sonstige Rechnung übermittelt werden. Zulässig sind XRechnung (KoSIT) und das Profil EN 16931 von ZUGFeRD, das mit Factur-X übereinstimmt; das Profil xrechnung ist hier genannt, weil es die nationale Ausprägung ist. vat_scheme 9930 ist die deutsche USt-IdNr. in der EAS-Liste. party_scheme bleibt leer: zwischen Unternehmern gibt es kein vorgeschriebenes Netz und keine Adresskennung, und die Leitweg-ID (EAS 0204) adressiert nur öffentliche Auftraggeber.',
  einvoice_source_key           = 'ustg',
  party_scheme                  = null,
  vat_scheme                    = '9930',
  bank_statement_formats        = array['camt.053']::text[],
  payment_formats               = array['pain.001', 'pain.008']::text[],
  fiscal_year_default           = 'calendar'
 where country = 'DE';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('DE', 'reverse_charge', 'reverse_charge', 'Steuerschuldnerschaft des Leistungsempfängers', '{"en":"Reverse charge — the recipient of the supply is liable for the tax"}'::jsonb, 10, date '1970-01-01', null, 'UStG § 14a Abs. 5 Satz 1 — bei Leistungen im Sinne des § 13b Abs. 2, für die der Leistungsempfänger nach § 13b Abs. 5 die Steuer schuldet, ist die Rechnung mit der Angabe „Steuerschuldnerschaft des Leistungsempfängers“ auszustellen; Satz 2 schließt den gesonderten Steuerausweis aus. Der Wortlaut ist gesetzlich vorgegeben.'),
  ('DE', 'intracom_goods', 'intra_eu_goods', 'Steuerfreie innergemeinschaftliche Lieferung', '{"en":"Exempt intra-Community supply of goods"}'::jsonb, 20, date '1970-01-01', null, 'UStG § 14 Abs. 4 Satz 1 Nr. 8 — im Fall einer Steuerbefreiung ein Hinweis darauf, dass für die Lieferung eine Steuerbefreiung gilt; § 14a Abs. 3 Satz 2 verlangt zusätzlich die Umsatzsteuer-Identifikationsnummern des Unternehmers und des Leistungsempfängers, die als Datenfelder der Rechnung und nicht als Satz ausgegeben werden.'),
  ('DE', 'intracom_services', 'intra_eu_services', 'Steuerschuldnerschaft des Leistungsempfängers', '{"en":"Reverse charge — the recipient of the supply is liable for the tax"}'::jsonb, 30, date '1970-01-01', null, 'UStG § 14a Abs. 1 Satz 1 — führt der im Inland ansässige Unternehmer einen Umsatz in einem anderen Mitgliedstaat aus, für den der Leistungsempfänger dort die Steuer schuldet, ist er zur Ausstellung einer Rechnung mit der Angabe „Steuerschuldnerschaft des Leistungsempfängers“ verpflichtet; Satz 2 und 3 verlangen die Rechnung bis zum 15. Tag des Folgemonats mit beiden Identifikationsnummern.'),
  ('DE', 'export', 'export', 'Steuerfreie Ausfuhrlieferung', '{"en":"Exempt export of goods"}'::jsonb, 40, date '1970-01-01', null, 'UStG § 14 Abs. 4 Satz 1 Nr. 8 — Hinweis auf die Steuerbefreiung nach § 4 Nr. 1 Buchst. a in Verbindung mit § 6.'),
  ('DE', 'exempt', 'exempt', 'Steuerfreier Umsatz nach § 4 UStG', '{"en":"Exempt supply under section 4 UStG"}'::jsonb, 50, date '1970-01-01', null, 'UStG § 14 Abs. 4 Satz 1 Nr. 8 — im Fall einer Steuerbefreiung ein Hinweis darauf, dass für die Lieferung oder sonstige Leistung eine Steuerbefreiung gilt. Das Gesetz schreibt für diesen Hinweis keinen Wortlaut vor.'),
  ('DE', 'small_business', 'small_business', 'Steuerfreier Umsatz nach § 19 UStG (Kleinunternehmerregelung)', '{"en":"Exempt under the small-business scheme, section 19 UStG"}'::jsonb, 60, date '1970-01-01', null, 'UStDV § 34a Satz 1 Nr. 5 — die Rechnung eines Kleinunternehmers enthält das Entgelt in einer Summe mit einem Hinweis darauf, dass für die Lieferung oder sonstige Leistung die Steuerbefreiung für Kleinunternehmer gilt (§ 19 UStG). Seit dem 1. Januar 2025 sind die Umsätze nach § 19 Abs. 1 UStG steuerfrei, wenn der Gesamtumsatz im Vorjahr 25 000 Euro nicht überschritten hat und im laufenden Jahr 100 000 Euro nicht überschreitet.'),
  ('DE', 'late_payment', 'late_payment', 'Bei Zahlungsverzug schuldet ein Schuldner, der nicht Verbraucher ist, Verzugszinsen in Höhe von neun Prozentpunkten über dem Basiszinssatz sowie eine Pauschale von 40 Euro (§ 288 Abs. 2 und 5 BGB).', '{"en":"A debtor who is not a consumer and pays late owes default interest of nine percentage points above the base rate and a flat fee of 40 euros (section 288(2) and (5) BGB)."}'::jsonb, 70, date '1970-01-01', null, 'BGB § 288 Abs. 2 — bei Rechtsgeschäften, an denen ein Verbraucher nicht beteiligt ist, beträgt der Zinssatz für Entgeltforderungen neun Prozentpunkte über dem Basiszinssatz; Abs. 5 — Pauschale von 40 Euro. Der Hinweis ist nicht vorgeschrieben; gegenüber einem Verbraucher tritt Verzug nach § 286 Abs. 3 Satz 1 ohne Mahnung nur ein, wenn die Rechnung auf diese Folge besonders hinweist.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
